1	import { getAllInstances } from '@clevercloud/client/esm/api/v2/application.js';
2	import { spawn } from 'node:child_process';
3	import { z } from 'zod';
4	import { config } from '../../config/config.js';
5	import { defineCommand } from '../../lib/define-command.js';
6	import { defineOption } from '../../lib/define-option.js';
7	import { selectAnswer } from '../../lib/prompts.js';
8	import * as Application from '../../models/application.js';
9	import { sendToApi } from '../../models/send-to-api.js';
10	import { aliasOption, appIdOrNameOption } from '../global.options.js';
11	
12	export const sshCommand = defineCommand({
13	  description: 'Connect to running instances through SSH',
14	  since: '0.7.0',
15	  options: {
16	    identityFile: defineOption({
17	      name: 'identity-file',
18	      schema: z.string().optional(),
19	      description: 'SSH identity file',
20	      aliases: ['i'],
21	      placeholder: 'identity-file',
22	    }),
23	    alias: aliasOption,
24	    app: appIdOrNameOption,
25	  },
26	  args: [],
27	  async handler(options) {
28	    const { alias, app: appIdOrName, identityFile } = options;
29	    const { appId, ownerId } = await Application.resolveId(appIdOrName, alias);
30	
31	    const instances = await getAllInstances({ id: ownerId, appId }).then(sendToApi);
32	
33	    if (instances.length === 0) {
34	      throw new Error('No running instances found for this application');
35	    }
36	
37	    let sshTarget;
38	    if (instances.length === 1) {
39	      sshTarget = instances[0].id;
40	    } else if (process.stdout.isTTY) {
41	      const choices = instances
42	        .sort((a, b) => a.instanceNumber - b.instanceNumber)
43	        .map((inst) => ({
44	          name: `${inst.displayName} - Instance ${inst.instanceNumber} - ${inst.state} (${inst.id})`,
45	          value: inst.id,
46	        }));
47	      sshTarget = await selectAnswer('Select an instance:', choices);
48	    } else {
49	      throw new Error('Multiple instances are running. Cannot select in non-interactive mode.');
50	    }
51	
52	    const sshParams = [];
53	    // -t: force PTY allocation (SSH skips it by default because appId is passed as a command for gateway routing)
54	    sshParams.push('-t');
55	    if (identityFile != null) {
56	      sshParams.push('-i', identityFile);
57	    }
58	    sshParams.push(config.SSH_GATEWAY, sshTarget);
59	
60	    return new Promise((resolve, reject) => {
61	      const sshProcess = spawn('ssh', sshParams, { stdio: 'inherit' });
62	      sshProcess.on('exit', resolve);
63	      sshProcess.on('error', reject);
64	    });
65	  },
66	});
